resources.fr = {
  translation: {
    ...((resources as any).frBase?.translation || {}),
    ...((resources as any).frExtra?.translation || {})
  }
};
delete (resources as any).frBase;
delete (resources as any).frExtra;

const enExtra = {
  translation: {
    load: "Load",
    unload: "Unload",
    assigned: "Assigned",
    dispatched: "Dispatched",
    new: "New",
    delivered: "Delivered",
    invoiced: "Invoiced",
  }
};

resources.en = {
  translation: {
    ...((resources as any).en?.translation || {}),
    ...enExtra.translation
  }
};

for (const lng of Object.keys(planningResources)) {
  const bundle = planningResources[lng];
  if (!(resources as any)[lng]) (resources as any)[lng] = { translation: {} };
  Object.assign((resources as any)[lng].translation, bundle.translation);
}

i18n.use(initReactI18next).init({
  resources,
  lng: localStorage.getItem('hapcargo_lang') || 'ro',
  fallbackLng: 'en',
  interpolation: { escapeValue: false },
});

export default i18n;






